.spatial-hero { position: relative; min-height: 480px; display: flex; align-items: center; justify-content: center; overflow: hidden; background: radial-gradient(circle at 50% 30%, rgba(139, 92, 246, 0.15), transparent 70%); }
.orb-glow { position: absolute; width: 320px; height: 320px; background: radial-gradient(circle, var(--uiv-primary), transparent 70%); opacity: 0.25; filter: blur(50px); pointer-events: none; }
.spatial-card { position: relative; z-index: 10; padding: 2.5rem; background: rgba(19, 20, 27, 0.7); backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: var(--uiv-radius); box-shadow: var(--uiv-shadow); text-align: center; max-width: 600px; }
.badge { display: inline-block; font-size: 11px; font-weight: 600; letter-spacing: 0.1em; color: var(--uiv-secondary); margin-bottom: 1rem; }
.spatial-card h1 { font-size: 2.2rem; font-weight: 700; line-height: 1.2; margin-bottom: 1rem; color: #fff; }
.spatial-card p { font-size: 1rem; color: #94a3b8; margin-bottom: 2rem; }
.cta-group { display: flex; gap: 1rem; justify-content: center; }
.btn-primary { background: var(--uiv-primary); color: #fff; border: none; padding: 0.75rem 1.75rem; border-radius: calc(var(--uiv-radius) / 2); font-weight: 600; cursor: pointer; transition: transform 0.2s; }
.btn-primary:hover { transform: translateY(-2px); }
.btn-secondary { background: transparent; color: #cbd5e1; border: 1px solid rgba(255,255,255,0.15); padding: 0.75rem 1.5rem; border-radius: calc(var(--uiv-radius) / 2); cursor: pointer; }

.auth-card { max-width: 420px; margin: 0 auto; padding: 2.25rem; background: rgba(22, 25, 35, 0.85); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: var(--uiv-radius); box-shadow: var(--uiv-shadow); }
.auth-header h2 { font-size: 1.5rem; font-weight: 700; margin-bottom: 0.5rem; color: #fff; }
.auth-header p { font-size: 0.875rem; color: #94a3b8; margin-bottom: 1.75rem; }
.input-group { margin-bottom: 1.25rem; display: flex; flex-direction: column; gap: 0.35rem; }
.input-group label { font-size: 0.8rem; font-weight: 500; color: #cbd5e1; }
.input-group input { background: rgba(11, 12, 16, 0.8); border: 1px solid rgba(255,255,255,0.1); border-radius: calc(var(--uiv-radius) / 2); padding: 0.75rem 1rem; color: #fff; font-size: 0.9rem; outline: none; transition: border-color 0.2s; }
.input-group input:focus { border-color: var(--uiv-primary); }
.form-options { display: flex; justify-content: space-between; font-size: 0.8rem; color: #94a3b8; margin-bottom: 1.5rem; }
.form-options a { color: var(--uiv-primary); text-decoration: none; }
.auth-submit { width: 100%; background: var(--uiv-primary); color: #fff; border: none; padding: 0.8rem; border-radius: calc(var(--uiv-radius) / 2); font-weight: 600; cursor: pointer; }

.glass-dashboard { padding: 1.5rem; background: #0d0f17; color: #fff; }
.dash-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.5rem; }
.btn-glass { background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.12); color: #fff; padding: 0.5rem 1.25rem; border-radius: var(--uiv-radius); cursor: pointer; }
.kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem; }
.kpi-card { background: rgba(25, 30, 45, 0.45); backdrop-filter: blur(16px); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: var(--uiv-radius); padding: 1.5rem; box-shadow: var(--uiv-shadow); }
.kpi-title { font-size: 0.8rem; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.05em; }
.kpi-value { font-size: 1.85rem; font-weight: 700; margin: 0.5rem 0; font-family: var(--font-mono); }
.kpi-change.positive { color: #10b981; font-size: 0.8rem; }
.kpi-change.neutral { color: #94a3b8; font-size: 0.8rem; }

.kinetic-hero { position: relative; min-height: 520px; display: flex; align-items: center; justify-content: center; text-align: center; overflow: hidden; background: #09090b; padding: 2rem; }
.gradient-mesh { position: absolute; top: -20%; left: 20%; width: 60%; height: 80%; background: radial-gradient(circle, rgba(236, 72, 153, 0.25) 0%, rgba(139, 92, 246, 0.15) 50%, transparent 80%); filter: blur(70px); pointer-events: none; }
.hero-content { position: relative; z-index: 2; max-width: 720px; }
.hero-kicker { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.15em; color: var(--uiv-primary); margin-bottom: 1rem; }
.hero-title { font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.15; color: #fff; margin-bottom: 1.25rem; text-wrap: balance; }
.hero-desc { font-size: 1.1rem; color: #a1a1aa; line-height: 1.6; margin-bottom: 2rem; }
.hero-actions { display: flex; gap: 1rem; justify-content: center; }
.btn-gradient { background: var(--uiv-accent-gradient, linear-gradient(135deg, var(--uiv-primary), var(--uiv-secondary))); color: #fff; border: none; padding: 0.85rem 2rem; border-radius: var(--uiv-radius); font-weight: 600; cursor: pointer; }
.btn-subtle { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1); color: #e4e4e7; padding: 0.85rem 1.75rem; border-radius: var(--uiv-radius); cursor: pointer; }

.ecom-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.5rem; }
.prod-card { background: #161822; border: 1px solid rgba(255,255,255,0.06); border-radius: var(--uiv-radius); overflow: hidden; transition: transform 0.2s, box-shadow 0.2s; }
.prod-card:hover { transform: translateY(-3px); box-shadow: var(--uiv-shadow); }
.prod-thumb { height: 220px; background: linear-gradient(145deg, #1f2333, #151722); position: relative; display: flex; align-items: center; justify-content: center; }
.prod-tag { position: absolute; top: 12px; left: 12px; background: rgba(0,0,0,0.6); backdrop-filter: blur(8px); padding: 4px 10px; border-radius: 6px; font-size: 11px; color: #f59e0b; font-weight: 600; }
.prod-info { padding: 1.25rem; }
.prod-cat { font-size: 11px; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.05em; }
.prod-name { font-size: 1.1rem; font-weight: 600; color: #fff; margin: 0.35rem 0 0.85rem; }
.prod-bottom { display: flex; justify-content: space-between; align-items: center; }
.prod-price { font-size: 1.15rem; font-weight: 700; color: #fff; font-family: var(--font-mono); }
.btn-add { background: var(--uiv-primary); color: #000; border: none; padding: 0.5rem 1rem; border-radius: 6px; font-weight: 600; cursor: pointer; }

.pdp-wrapper { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; background: #11131a; border-radius: var(--uiv-radius); padding: 2rem; border: 1px solid rgba(255,255,255,0.06); }
.media-display { height: 320px; background: radial-gradient(circle, #252a3d 0%, #151722 100%); border-radius: calc(var(--uiv-radius) / 2); display: flex; align-items: center; justify-content: center; position: relative; }
.waveform-indicator { font-family: var(--font-mono); font-size: 0.85rem; color: #94a3b8; border: 1px solid rgba(255,255,255,0.1); padding: 6px 14px; border-radius: 20px; }
.pdp-kicker { font-size: 0.75rem; letter-spacing: 0.1em; color: var(--uiv-primary); font-weight: 600; }
.pdp-details h1 { font-size: 2rem; font-weight: 700; color: #fff; margin: 0.5rem 0 1rem; }
.pdp-price { font-size: 1.6rem; font-weight: 700; color: #fff; font-family: var(--font-mono); margin-bottom: 1rem; }
.stock-badge { font-size: 0.8rem; color: #10b981; margin-left: 0.75rem; font-weight: 500; }
.pdp-desc { color: #94a3b8; line-height: 1.5; margin-bottom: 1.75rem; font-size: 0.95rem; }
.btn-buy { width: 100%; background: var(--uiv-primary); color: #fff; border: none; padding: 0.9rem; font-weight: 600; border-radius: calc(var(--uiv-radius) / 2); cursor: pointer; }

.pricing-wrap { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; max-width: 900px; margin: 0 auto; }
.plan-card { background: #13151f; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); padding: 2rem 1.5rem; display: flex; flex-direction: column; text-align: left; position: relative; }
.plan-card.highlighted { border-color: var(--uiv-primary); background: #171926; box-shadow: var(--uiv-shadow); }
.plan-badge { position: absolute; top: -11px; right: 20px; background: var(--uiv-primary); color: #fff; font-size: 10px; font-weight: 700; padding: 2px 10px; border-radius: 20px; }
.plan-type { font-size: 1.15rem; font-weight: 700; color: #fff; margin-bottom: 0.5rem; }
.plan-price { font-size: 2.2rem; font-weight: 800; color: #fff; font-family: var(--font-mono); }
.plan-price span { font-size: 0.95rem; font-weight: 400; color: #94a3b8; }
.plan-sub { font-size: 0.85rem; color: #94a3b8; margin: 0.75rem 0 1.5rem; flex-grow: 1; }
.btn-plan { background: rgba(255,255,255,0.06); color: #fff; border: 1px solid rgba(255,255,255,0.1); padding: 0.75rem; border-radius: calc(var(--uiv-radius) / 2); font-weight: 600; cursor: pointer; }
.btn-plan.primary { background: var(--uiv-primary); border: none; color: #fff; }

.hub-wrap { background: #13141b; border: 1px solid rgba(255,255,255,0.06); border-radius: var(--uiv-radius); padding: 1.5rem; }
.hub-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; }
.hub-top h3 { color: #fff; font-size: 1.15rem; font-weight: 700; }
.hub-top p { color: #94a3b8; font-size: 0.8rem; }
.btn-audit { background: var(--uiv-primary); color: #000; border: none; padding: 0.45rem 1rem; border-radius: 6px; font-weight: 600; font-size: 0.8rem; cursor: pointer; }
.hub-bars { display: flex; align-items: flex-end; justify-content: space-around; height: 180px; gap: 0.5rem; padding-bottom: 1.5rem; border-bottom: 1px solid rgba(255,255,255,0.06); }
.bar-col { flex: 1; max-width: 40px; background: rgba(255,255,255,0.1); border-radius: 4px; position: relative; transition: height 0.3s ease; }
.bar-col.active { background: var(--uiv-primary); }
.bar-col span { position: absolute; bottom: -24px; left: 50%; transform: translateX(-50%); font-size: 11px; color: #64748b; }

.term-window { background: #0c0d14; border: 1px solid rgba(255,255,255,0.1); border-radius: var(--uiv-radius); overflow: hidden; font-family: var(--font-mono); box-shadow: var(--uiv-shadow); }
.term-bar { background: #151722; padding: 0.6rem 1rem; display: flex; align-items: center; gap: 6px; }
.dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.dot.red { background: #ef4444; }
.dot.yellow { background: #f59e0b; }
.dot.green { background: #10b981; }
.term-title { margin-left: 10px; font-size: 12px; color: #94a3b8; }
.term-body { padding: 1.5rem; line-height: 1.7; font-size: 0.85rem; color: #cbd5e1; }
.prompt { color: var(--uiv-primary); font-weight: 700; }
.res { color: #94a3b8; margin-bottom: 0.75rem; }
.status-ok { color: var(--uiv-primary); }

.agency-hero { padding: 4rem 2rem; background: #09090b; border: 1px solid rgba(255,255,255,0.06); border-radius: var(--uiv-radius); text-align: left; }
.agency-kicker { font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em; color: #a1a1aa; margin-bottom: 1.5rem; }
.agency-head { font-size: clamp(2rem, 5vw, 3.6rem); font-weight: 800; color: #fff; letter-spacing: -0.02em; line-height: 1.1; margin-bottom: 1.5rem; max-width: 800px; }
.agency-bio { font-size: 1.1rem; color: #71717a; max-width: 580px; line-height: 1.6; margin-bottom: 2rem; }
.btn-monochrome { background: #fff; color: #000; border: none; padding: 0.85rem 2rem; font-weight: 700; border-radius: 4px; cursor: pointer; }

.fluid-nav { display: flex; align-items: center; justify-content: space-between; padding: 0.75rem 1.5rem; background: rgba(17, 19, 28, 0.85); backdrop-filter: blur(16px); border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); max-width: 960px; margin: 0 auto; }
.nav-brand { font-weight: 800; font-size: 1.1rem; color: #fff; }
.nav-links { display: flex; gap: 1.5rem; font-size: 0.875rem; }
.nav-links a { color: #94a3b8; text-decoration: none; transition: color 0.2s; }
.nav-links a.active, .nav-links a:hover { color: #fff; }
.nav-actions { display: flex; gap: 0.75rem; align-items: center; }
.btn-cmd { background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1); color: #cbd5e1; padding: 0.35rem 0.75rem; border-radius: 8px; font-size: 0.8rem; cursor: pointer; display: flex; align-items: center; gap: 6px; }
.cmd-key { font-family: var(--font-mono); background: rgba(0,0,0,0.4); padding: 2px 5px; border-radius: 4px; font-size: 10px; }
.btn-sign { background: var(--uiv-primary); color: #fff; border: none; padding: 0.45rem 1rem; border-radius: 8px; font-size: 0.85rem; font-weight: 600; cursor: pointer; }

.sb-rail { width: 240px; background: #11131c; border-right: 1px solid rgba(255,255,255,0.06); padding: 1.25rem; display: flex; flex-direction: column; min-height: 380px; border-radius: var(--uiv-radius); }
.sb-team { display: flex; align-items: center; gap: 0.75rem; margin-bottom: 1.5rem; padding-bottom: 1rem; border-bottom: 1px solid rgba(255,255,255,0.06); }
.team-icon { width: 32px; height: 32px; background: var(--uiv-primary); color: #fff; font-weight: 700; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 12px; }
.team-name { font-size: 0.85rem; font-weight: 600; color: #fff; display: block; }
.team-role { font-size: 0.75rem; color: #94a3b8; }
.sb-menu { display: flex; flex-direction: column; gap: 4px; flex-grow: 1; }
.sb-link { display: flex; justify-content: space-between; align-items: center; padding: 0.5rem 0.75rem; color: #94a3b8; text-decoration: none; border-radius: 6px; font-size: 0.85rem; }
.sb-link.active, .sb-link:hover { background: rgba(255,255,255,0.05); color: #fff; }
.count { background: rgba(255,255,255,0.1); font-size: 10px; padding: 1px 6px; border-radius: 10px; }
.btn-new-proj { background: var(--uiv-primary); color: #fff; border: none; padding: 0.6rem; border-radius: 6px; font-size: 0.85rem; font-weight: 600; cursor: pointer; }

.btn-suite-grid { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; padding: 1.5rem; background: #11131c; border-radius: var(--uiv-radius); }
.btn-uiv { padding: 0.75rem 1.5rem; font-size: 0.85rem; font-weight: 600; border-radius: var(--uiv-radius); cursor: pointer; transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1); outline: none; }
.btn-shimmer { background: linear-gradient(90deg, #8b5cf6, #ec4899, #8b5cf6); background-size: 200% auto; color: #fff; border: none; }
.btn-shimmer:hover { background-position: right center; transform: scale(1.02); }
.btn-neon { background: transparent; border: 1px solid var(--uiv-primary); color: var(--uiv-primary); box-shadow: 0 0 10px rgba(139, 92, 246, 0.2); }
.btn-neon:hover { background: var(--uiv-primary); color: #fff; box-shadow: 0 0 18px rgba(139, 92, 246, 0.5); }
.btn-magnetic { background: #1e2130; color: #fff; border: 1px solid rgba(255,255,255,0.1); }
.btn-magnetic:hover { transform: translateY(-2px); border-color: rgba(255,255,255,0.3); }
.btn-glass-pop { background: rgba(255,255,255,0.06); backdrop-filter: blur(8px); color: #fff; border: 1px solid rgba(255,255,255,0.12); }
.btn-glass-pop:hover { background: rgba(255,255,255,0.12); }

.bento-card { background: #131520; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); padding: 1.5rem; max-width: 440px; margin: 0 auto; box-shadow: var(--uiv-shadow); }
.bento-head { display: flex; align-items: center; gap: 0.85rem; margin-bottom: 1.5rem; position: relative; }
.avatar { width: 44px; height: 44px; background: var(--uiv-primary); color: #fff; font-weight: 700; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 14px; }
.bento-head h3 { font-size: 1.05rem; font-weight: 700; color: #fff; }
.bento-head p { font-size: 0.75rem; color: #94a3b8; }
.status-pill { position: absolute; right: 0; top: 0; font-size: 11px; color: #10b981; font-weight: 600; }
.bento-stats { display: grid; grid-template-columns: repeat(3, 1fr); text-align: center; background: rgba(255,255,255,0.03); border-radius: 8px; padding: 0.85rem; margin-bottom: 1.25rem; }
.bento-stats .val { display: block; font-size: 1.25rem; font-weight: 700; color: #fff; font-family: var(--font-mono); }
.bento-stats .lbl { font-size: 11px; color: #94a3b8; }
.btn-contact { width: 100%; background: var(--uiv-primary); color: #fff; border: none; padding: 0.65rem; border-radius: 8px; font-weight: 600; cursor: pointer; }

.testi-card { background: #13141f; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); padding: 2rem; max-width: 520px; margin: 0 auto; }
.stars { color: #f59e0b; margin-bottom: 1rem; font-size: 1.1rem; letter-spacing: 2px; }
.quote { font-size: 1.05rem; line-height: 1.6; color: #e2e8f0; font-style: italic; margin-bottom: 1.5rem; }
.author-block { display: flex; align-items: center; gap: 0.85rem; }
.author-av { width: 40px; height: 40px; border-radius: 50%; background: #262a3d; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; color: #fff; }
.name { display: block; font-size: 0.95rem; font-weight: 600; color: #fff; }
.role { font-size: 0.8rem; color: #94a3b8; }

.inq-form { background: #12141e; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); padding: 1.75rem; max-width: 480px; margin: 0 auto; }
.inq-form h3 { font-size: 1.25rem; font-weight: 700; color: #fff; margin-bottom: 1.25rem; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin-bottom: 1rem; }
.inq-form input, .inq-form textarea { width: 100%; background: #0c0e15; border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; padding: 0.75rem; color: #fff; font-size: 0.85rem; box-sizing: border-box; }
.scope-chips { display: flex; gap: 0.5rem; margin-bottom: 1rem; font-size: 0.8rem; color: #cbd5e1; }
.scope-chip { background: #1a1d2c; padding: 4px 10px; border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 4px; }
.btn-inq { width: 100%; background: var(--uiv-primary); color: #fff; border: none; padding: 0.75rem; border-radius: 8px; font-weight: 600; margin-top: 1rem; cursor: pointer; }

.nl-box { background: #131520; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); padding: 2rem; max-width: 520px; margin: 0 auto; text-align: center; }
.nl-box h4 { font-size: 1.35rem; font-weight: 700; color: #fff; margin-bottom: 0.5rem; }
.nl-box p { font-size: 0.85rem; color: #94a3b8; margin-bottom: 1.5rem; }
.nl-bar { display: flex; gap: 0.5rem; background: #0c0e15; border: 1px solid rgba(255,255,255,0.1); border-radius: var(--uiv-radius); padding: 4px; }
.nl-bar input { flex-grow: 1; background: transparent; border: none; padding: 0.65rem 1rem; color: #fff; font-size: 0.85rem; outline: none; }
.nl-bar button { background: var(--uiv-primary); color: #000; border: none; padding: 0.65rem 1.25rem; border-radius: calc(var(--uiv-radius) - 4px); font-weight: 600; cursor: pointer; }
.nl-note { display: block; margin-top: 0.85rem; font-size: 11px; color: #64748b; }

.masonry-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; max-width: 500px; margin: 0 auto; }
.m-item { border-radius: var(--uiv-radius); background: linear-gradient(145deg, #1d2130, #131522); position: relative; overflow: hidden; display: flex; align-items: flex-end; cursor: pointer; transition: transform 0.2s; }
.m-item:hover { transform: scale(1.02); }
.m-item.tall { height: 180px; }
.m-item.short { height: 120px; }
.m-overlay { width: 100%; padding: 0.75rem; background: linear-gradient(to top, rgba(0,0,0,0.8), transparent); }
.m-overlay span { font-size: 11px; font-weight: 600; color: #fff; }

.kpi-deck-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; max-width: 500px; margin: 0 auto; }
.kpi-tile { background: #131520; border: 1px solid rgba(255,255,255,0.06); border-radius: var(--uiv-radius); padding: 1.25rem; }
.tile-lbl { font-size: 11px; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.05em; }
.tile-val { font-size: 1.6rem; font-weight: 700; color: #fff; font-family: var(--font-mono); margin: 0.4rem 0; }
.tile-delta { font-size: 11px; font-weight: 600; }
.tile-delta.pos { color: #10b981; }

.chat-box { background: #12141f; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--uiv-radius); max-width: 480px; margin: 0 auto; overflow: hidden; }
.chat-bar { padding: 0.85rem 1.25rem; background: #161926; font-weight: 700; color: #fff; font-size: 0.9rem; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.06); }
.chat-bar small { font-weight: 400; color: #10b981; font-size: 11px; }
.chat-thread { padding: 1.25rem; display: flex; flex-direction: column; gap: 1rem; min-height: 180px; }
.msg { display: flex; gap: 0.75rem; }
.msg.sent { justify-content: flex-end; }
.msg-av { width: 32px; height: 32px; border-radius: 50%; background: #3b82f6; color: #fff; font-size: 11px; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.msg-body { background: #1b1e2c; padding: 0.6rem 0.85rem; border-radius: 10px; max-width: 300px; font-size: 0.85rem; }
.msg.sent .msg-body { background: var(--uiv-primary); color: #fff; }
